#GENERATED BY FORWARD
CDAUT01R_1=CLOSE authcursordn 
CDAUT01R_2=DECLARE authcursordn FOR select AUTHID, TRNID, CARDNUM, RESPONSE, RSPREASON, FRAUDFLAG, AUTHDATE, AUTHTIME, AUTHUSER, AUTHPGM from CDAUTP where AUTHID <= ? order by AUTHID DESC for read only
CDAUT01R_3=OPEN authcursordn 
CDAUT01R_4=CLOSE authcursorup 
CDAUT01R_5=DECLARE authcursorup FOR select AUTHID,TRNID,CARDNUM,RESPONSE,RSPREASON,FRAUDFLAG,AUTHDATE,AUTHTIME,AUTHUSER,AUTHPGM from CDAUTP where AUTHID>? order by AUTHID ASC
CDAUT01R_6=OPEN authcursorup 
CDAUT01R_7=FETCH PRIOR authcursordn
CDAUT01R_8=FETCH NEXT authcursordn
CDAUT01R_9=FETCH FIRST authcursorup
CDAUT01R_10=FETCH LAST authcursorup
